      db.prepare('UPDATE orders SET fulfillment=?,carrier=?,tracking=?,notes=? WHERE id=? AND EXISTS(SELECT 1 FROM order_events WHERE id=?)').bind(b.fulfillment,b.carrier.trim(),b.tracking.trim(),b.notes.trim(),row.id,marker)
